-- Per-class tuition (Stream 5): TuitionCharge ledger + online-payment columns on tuition_payments.
-- ADDITIVE: nothing is dropped or rewritten. Part 1 is the DDL (generated by `prisma migrate diff`).
-- Part 2 is one backfill: a CLASSES charge (plannedClasses x ratePerClass) for each plan_agreed /
-- enrolled enrollment that already has an agreed plan and no charges, so its balance is exactly what
-- Streams 2+3 showed. Legacy enrollments (no plan fields) are NOT touched and keep the old
-- Course.pricing balance. DEPLOY NOTE: snapshot production first; migrate with a direct DB URL.

-- ============================== Part 1: DDL ==============================

-- AlterTable
ALTER TABLE "tuition_payments" ADD COLUMN     "paymentUrl" TEXT,
ADD COLUMN     "paystackChannel" TEXT,
ADD COLUMN     "paystackReference" TEXT;

-- CreateTable
CREATE TABLE "tuition_charges" (
    "id" TEXT NOT NULL,
    "enrollmentId" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "origin" TEXT NOT NULL DEFAULT 'ADJUSTMENT',
    "quantity" INTEGER NOT NULL,
    "unitPrice" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    "materialId" TEXT,
    "createdBy" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "voidedAt" TIMESTAMP(3),
    "voidedBy" TEXT,
    "voidReason" TEXT,

    CONSTRAINT "tuition_charges_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "tuition_charges_enrollmentId_idx" ON "tuition_charges"("enrollmentId");

-- CreateIndex
CREATE INDEX "tuition_charges_materialId_idx" ON "tuition_charges"("materialId");

-- CreateIndex
CREATE UNIQUE INDEX "tuition_payments_paystackReference_key" ON "tuition_payments"("paystackReference");

-- AddForeignKey
ALTER TABLE "tuition_charges" ADD CONSTRAINT "tuition_charges_enrollmentId_fkey" FOREIGN KEY ("enrollmentId") REFERENCES "enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "tuition_charges" ADD CONSTRAINT "tuition_charges_materialId_fkey" FOREIGN KEY ("materialId") REFERENCES "materials"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ============================== Part 2: backfill ==============================
-- createdAt = the enrollment's creation time so the charge predates every payment (point-in-time
-- receipts include only charges created before the payment). Idempotent: deterministic id + NOT EXISTS.
INSERT INTO "tuition_charges" ("id", "enrollmentId", "kind", "origin", "quantity", "unitPrice", "description", "createdAt")
SELECT 'backfill_' || e."id", e."id", 'CLASSES', 'PLAN', e."plannedClasses", e."ratePerClass",
       e."plannedClasses"::text || CASE WHEN e."durationMins" IS NULL THEN ' classes' ELSE ' x ' || e."durationMins"::text || '-minute classes' END,
       e."createdAt"
FROM "enrollments" e
WHERE e."status" IN ('plan_agreed', 'enrolled')
  AND e."ratePerClass" IS NOT NULL
  AND e."plannedClasses" IS NOT NULL
  AND e."plannedClasses" > 0
  AND NOT EXISTS (SELECT 1 FROM "tuition_charges" c WHERE c."enrollmentId" = e."id")
ON CONFLICT ("id") DO NOTHING;

DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM "tuition_charges" WHERE "id" LIKE 'backfill\_%';
  RAISE NOTICE 'per_class_tuition: % plan enrollment(s) backfilled with a CLASSES charge', n;
END $$;
